INSERT INTO public.organizations (id,kind,city,title,category,description,address,phone,website,source_type,source_url,verified_at,status) VALUES
  ('place-culture-center-eniseysk', 'places', 'Енисейск', 'Культурный центр г. Енисейска', 'Культура', 'Культурный центр Енисейска — пространство для творческой жизни города, занятий в студиях и участия в культурных программах. Здесь встречаются люди, интересующиеся искусством и местными инициативами; сведения о центре и контакты доступны в карточке.', 'ул. Ленина, 130', '+7 (39195) 2-24-63', NULL, 'manual_verified', 'https://www.culture.ru/institutes/103034/kulturnyi-centr-g-eniseiska', '2026-10-14', 'published'),
  ('place-gdk-arutyunyan', 'places', 'Енисейск', 'Городской дом культуры им. А. О. Арутюняна', 'Культура', 'Городской дом культуры имени А. О. Арутюняна — одна из площадок культурной жизни Енисейска. Здесь работают творческие коллективы и клубные объединения, а жители могут познакомиться с городской культурной программой и направлениями досуга.', 'ул. Ленина, 44', '+7 (39195) 2-22-15', NULL, 'manual_verified', 'https://www.culture.ru/institutes/73661/gorodskoi-dom-kultury-im-a-o-arutyunyana', '2026-10-14', 'published'),
  ('place-central-library', 'places', 'Енисейск', 'Центральная библиотека Енисейска', 'Библиотеки', 'Центральная библиотека Енисейска объединяет любовь к книгам и атмосферу исторического города: она размещается в доме купца Савельева. Сюда можно заглянуть за чтением, библиотечными услугами и знакомством с культурной жизнью Енисейска.', 'ул. Ленина, 95', NULL, NULL, 'manual_verified', 'https://www.culture.ru/institutes/85017/centralnaya-biblioteka-g-eniseiska', '2026-10-14', 'published'),
  ('place-childrens-library', 'places', 'Енисейск', 'Городская детская библиотека', 'Библиотеки', 'Городская детская библиотека Енисейска — место, где дети знакомятся с книгами и находят новые истории. Книжный фонд, читальный зал и познавательные мероприятия делают библиотеку полезной точкой для семейного досуга и школьного чтения.', 'ул. Петровского, 7', NULL, NULL, 'manual_verified', 'https://www.culture.ru/institutes/51329/gorodskaya-detskaya-biblioteka-eniseiska', '2026-10-14', 'published'),
  ('place-library-branch-1', 'places', 'Енисейск', 'Библиотека-филиал № 1', 'Библиотеки', 'Библиотека-филиал № 1 в Енисейске работает в здании молодёжного центра. Это место для чтения, общения и участия в культурных встречах: удобно заглянуть за книгой или узнать о библиотечных мероприятиях рядом с домом.', 'ул. Декабристов, 1', NULL, NULL, 'manual_verified', 'https://www.culture.ru/institutes/55240/biblioteka-filial-1-g-eniseiska', '2026-10-14', 'published'),
  ('place-hotel-eniseyskaya', 'places', 'Енисейск', 'Гостиница «Енисейская»', 'Гостиницы', 'Гостиница «Енисейская» — вариант размещения для гостей Енисейска, которые хотят остановиться ближе к городской инфраструктуре. На официальном сайте можно узнать о категориях номеров и условиях проживания перед поездкой.', 'ул. Ленина, 133', '+7 (39195) 2-63-58', 'https://hotelenisei.ru/', 'manual_verified', 'https://hotelenisei.ru/', '2026-10-14', 'published'),
  ('place-hotel-domino', 'places', 'Енисейск', 'Гостиница «Домино»', 'Гостиницы', 'Гостиница «Домино» в Енисейске предлагает размещение для путешественников и гостей города. Перед бронированием стоит уточнить наличие номеров, стоимость и условия проживания; адрес гостиницы и ссылка на справочник указаны в карточке.', 'ул. Петровского, 2/1', NULL, NULL, 'manual_verified', 'https://2gis.ru/enisejsk/firm/70000001046023115', '2026-10-14', 'published'),
  ('place-cafe-domino', 'places', 'Енисейск', 'Кафе «Домино»', 'Кафе', 'Кафе «Домино» — место в Енисейске, куда можно зайти на обед или перекус. В открытом справочнике представлены блюда повседневного меню; расположение и ссылка на страницу заведения помогут выбрать удобную остановку в городе.', 'ул. Петровского, 2/1', NULL, NULL, 'manual_verified', 'https://2gis.ru/enisejsk/firm/70000001066555159', '2026-10-14', 'published'),
  ('place-myasorubka', 'places', 'Енисейск', 'Бургерная «Мясорубка»', 'Кафе', '«Мясорубка» — бургерная Енисейска с атмосферой стритфуда, где главное внимание уделено бургерам. В справочнике также отмечены картофель фри, закуски и доставка. Хороший вариант для сытного перекуса или встречи с друзьями; актуальное меню лучше уточнить перед заказом.', 'ул. Бабкина, 8', NULL, NULL, 'manual_verified', 'https://2gis.ru/enisejsk/firm/70000001064232362', '2026-10-14', 'published'),
  ('place-skazka', 'places', 'Енисейск', 'Ресторан «Сказка»', 'Кафе', '«Сказка» — ресторан русской кухни в Енисейске для тех, кто хочет пообедать или провести время за знакомыми домашними блюдами. В открытом меню упоминаются пельмени, супы и салаты; перед визитом можно проверить предложения и режим работы.', 'ул. Петровского, 11а', NULL, NULL, 'manual_verified', 'https://2gis.ru/enisejsk/search/%D0%9F%D0%BE%D0%B5%D1%81%D1%82%D1%8C', '2026-10-14', 'published'),
  ('place-veles', 'places', 'Енисейск', 'Кафе «Велес»', 'Кафе', '«Велес» — кафе Енисейска с выбором блюд для быстрого перекуса и полноценного обеда. В справочнике указаны шаурма, пицца, супы и другие позиции; уточнить меню и условия заказа удобно по источнику в карточке.', 'ул. Кирова, 87', NULL, NULL, 'manual_verified', 'https://2gis.ru/enisejsk/firm/70000001053695069', '2026-10-14', 'published'),
  ('place-sibirskiy-zames', 'places', 'Енисейск', 'Кафе «Сибирский замес»', 'Кафе', '«Сибирский замес» — кафе Енисейска с акцентом на домашнюю кухню. Здесь ищут знакомые вкусы: в справочнике упомянуты пельмени и драники, а также возможность взять кофе. Подойдёт для обеда и знакомства с местными гастрономическими точками.', 'ул. Худзинского, 1', NULL, NULL, 'manual_verified', 'https://2gis.ru/enisejsk/firm/70000001088723956', '2026-10-14', 'published'),
  ('place-sushisell', 'places', 'Енисейск', 'СушиSell', 'Кафе', 'СушиSell — служба доставки суши и роллов в Енисейске, представленная в городском справочнике. Подойдёт тем, кто выбирает блюда японской и азиатской кухни для заказа; актуальные позиции меню, адрес и условия доставки стоит проверить перед оформлением.', 'Партизанский пер., 3', NULL, NULL, 'manual_verified', 'https://2gis.ru/enisejsk/search/%D0%A1%D1%83%D1%88%D0%B8', '2026-10-14', 'published'),
  ('place-volna', 'places', 'Енисейск', 'Столовая «Волна»', 'Кафе', '«Волна» — столовая в Енисейске для тех, кто ищет простой и понятный формат обеда. Её адрес указан в туристическом буклете города; актуальное меню и часы обслуживания лучше уточнить непосредственно перед посещением.', 'ул. Бабкина, 4', NULL, NULL, 'manual_verified', 'https://visitsiberia.info/assets/manager/Poleznoe/buklet/buklet-enisejsk.pdf', '2026-10-14', 'published'),
  ('place-bulofnaya', 'places', 'Енисейск', 'Пекарня «БулоФная»', 'Кафе', '«БулоФная» — пекарня в Енисейске, которую стоит добавить в список мест для повседневных покупок выпечки. Загляните в карточку, чтобы найти адрес и перейти к справочнику; актуальный ассортимент и график работы лучше уточнить на месте.', 'ул. Ванеева, 1а', NULL, NULL, 'manual_verified', 'https://2gis.ru/enisejsk/search/%D0%9F%D0%B5%D0%BA%D0%B0%D1%80%D0%BD%D1%8F', '2026-10-14', 'published'),
  ('service-mfc-eniseysk', 'services', 'Енисейск', 'МФЦ «Мои документы»', 'Госуслуги', 'МФЦ «Мои документы» в Енисейске помогает жителям обращаться за государственными и муниципальными услугами в одном месте. Адрес отделения, контактный телефон и ссылка на официальный сайт пригодятся, чтобы уточнить порядок обращения перед визитом.', 'ул. Ленина, 89', '+7 (39195) 2-64-33', 'https://24mfc.ru/', 'manual_verified', 'https://24mfc.ru/about/detail.php?ELEMENT_ID=439235', '2026-10-14', 'published'),
  ('service-post-663180', 'services', 'Енисейск', 'Почта России — отделение 663180', 'Почта', 'Почтовое отделение № 663180 в Енисейске — точка обращения за услугами Почты России. В карточке собраны адрес и ссылка на официальный сайт, где можно проверить режим работы, доступные операции и информацию об отправлениях перед посещением.', 'ул. Ленина, 10', NULL, 'https://www.pochta.ru/offices/663180', 'manual_verified', 'https://www.pochta.ru/offices/663180', '2026-10-14', 'published')
